            <div className="space-y-3">
              {teamIntel.memberRecords.map((rec) => {
                const { member, profile, isLeader } = rec;
                return (
                  <div
                    key={member.id}
                    onClick={() => onInspectProfile && onInspectProfile(profile)}
                    className={`p-3.5 rounded-2xl border transition-all ${
