  UserX,
  MessageSquare,
  Lock,
  Unlock,
  Send,
  ShieldCheck,
  Sparkles,
  Plus,
  Rocket,
  FolderGit2,
  Activity,
  CheckCircle2,
  X,
} from 'lucide-react';
import { UserAvatar } from './UserAvatar';

interface TeamLeaderDashboardProps {
  onOpenChat: (applicationId: string) => void;
  onOpenTeamPage?: (teamOrId: any) => void;
}

const COMMON_SKILLS = [
  'C++',
  'C',
  'Data Structures',
  'Algorithms',
  'STL',
  'Multithreading',
  'Python',
