  emoji: string;
  label: string;
  bgGradient: string;
}

export const AVATAR_EMOJI_OPTIONS: AvatarEmojiOption[] = [
  { emoji: '👨‍💻', label: 'Systems Coder', bgGradient: 'from-indigo-600 to-violet-600' },
  { emoji: '👩‍💻', label: 'Tech Lead', bgGradient: 'from-violet-600 to-purple-600' },
